<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Document\Template\Domain\TemplateRef;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\ValueObject\Accessor\TemplateVersionTemplateAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TemplateVersionTemplateAccessor trait.
 *
 * Covers null default, string/VO assignment via withTemplate,
 * getTemplate/template accessors, and isTemplateChanged with/without original.
 */
class TemplateVersionTemplateAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withTemplate creates a new instance with the Template set
     * from a string value, and getTemplate returns the primitive string.
     */
    public function testWithTemplateFromString(): void
    {
        // Arrange
        $holder = new ImplWithTemplateVersionTemplateAccessorUnitTest();

        // Act
        $result = $holder->withTemplate(new TemplateRef('one'));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(new TemplateRef('one'), $result->getTemplate());
    }
    /**
     * Asserts that withtemplate has access to the value object
     * from a string value, and getTemplate returns the primitive string.
     */
    public function testWithTemplateFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTemplateVersionTemplateAccessorUnitTest();

        // Act
        $result = $holder->withTemplate(new TemplateRef('one'));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(new TemplateRef('one'), $result->template()->value());
    }
    public function testChangedTemplate(): void
    {
        // Arrange
        $holder = new ImplWithTemplateVersionTemplateAccessorUnitTest()->withTemplate(new TemplateRef('one'));
        $original = $holder->withTemplate( new TemplateRef('one'));
        $same = $holder->withTemplate( new TemplateRef('one'));
        $modified = $holder->withTemplate(new TemplateRef('other'));

        // Act
        $withSame = $original->isTemplateChanged( $same );
        $withDiferent = $original->isTemplateChanged( $modified );

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTemplateVersionTemplateAccessorUnitTest
{
  use TemplateVersionTemplateAccessor;
}
